from app.database.db import db

RECOMMENDATION_STATUSES = ("PENDING", "COMPLETED", "DISMISSED")
RECOMMENDATION_PRIORITIES = ("HIGH", "MEDIUM", "LOW")
RECOMMENDATION_CATEGORIES = (
    "DOCUMENTATION_GAP",
    "MISSING_RELATIONSHIPS",
    "LOW_COVERAGE",
    "ORGANIZATION_ISSUE",
    "CATEGORY_BALANCE",
    "EXPANSION_OPPORTUNITY",
)


class CompassRecommendation(db.Model):
    """Persistent evidence-backed recommendation generated by the Progress Engine."""

    __tablename__ = "compass_recommendations"

    id = db.Column(db.Integer, primary_key=True)
    dedupe_key = db.Column(db.String(200), unique=True, nullable=False, index=True)
    rule_code = db.Column(db.String(64), nullable=False)
    title = db.Column(db.String(200), nullable=False)
    explanation = db.Column(db.Text, nullable=False)
    category = db.Column(db.String(50), nullable=False)
    priority = db.Column(db.String(20), nullable=False, default="MEDIUM", index=True)

    entity_type = db.Column(db.String(30), nullable=True, index=True)
    entity_id = db.Column(db.Integer, nullable=True, index=True)
    entity_slug = db.Column(db.String(200), nullable=True)
    entity_label = db.Column(db.String(200), nullable=True)

    evidence_json = db.Column(db.Text, nullable=False, default="{}")
    suggested_action = db.Column(db.Text, nullable=False)
    action_target = db.Column(db.String(50), nullable=False, default="library")

    status = db.Column(db.String(20), nullable=False, default="PENDING", index=True)
    is_active = db.Column(db.Boolean, nullable=False, default=True)
    resolved_at = db.Column(db.DateTime, nullable=True)

    created_at = db.Column(
        db.DateTime,
        server_default=db.func.now(),
        nullable=False,
    )
    updated_at = db.Column(
        db.DateTime,
        server_default=db.func.now(),
        onupdate=db.func.now(),
        nullable=True,
    )

    def __repr__(self):
        return f"<CompassRecommendation {self.dedupe_key} [{self.status}/{self.priority}]>"
